      "exercisesNote": "Trả lời câu hỏi đọc hiểu (tr. 17).\n1. 玛丽现在在哪儿？\n2. 她现在生活得怎么样？\n3. 她参加了一个什么班？\n4. 她以前会用筷子吗？\n5. 她来中国多长时间了？\n6. 介绍一下这几张照片。\nMục 1–2 luyện ngữ âm và cụm từ tr. 22–23. Mục 3 chọn từ tr. 23–24. Mục 4–5 hoàn thành câu và hội thoại tr. 24–25. Mục 6 nối câu thành đoạn tr. 25. Mục 7 sửa câu tr. 25–26. Mục 8 biểu đạt theo tình huống tr. 26. Mục 9 điền tổng hợp 《雪后爬长城》 và từ bổ sung tr. 26–27.",
      "answerKeyNote": "Phụ lục tr. 173–174.\nMục 6: (1) A C D B; (2) C B D A E.\nMục 7:\n1. 一切困难我都不怕。\n2. 我昨天叫她别去，可是她还是去了，我白说了。\n3. 他每天早上在公园里打太极拳，练气功。\n4. 各国都有不同的习惯和想法。\n5. 我躺在床上翻来倒去睡不着。\n6. 我把这里的景色照了下来。／我把这里的景色拍了下来。\nMục 9: (1) 可是; (2) 出来; (3) 就; (4) 吧; (5) 去; (6) 得; (7) 才; (8) 还."
