        "zh": "国庆节放假期间，正是北京一年中风景最美的时候。每到国庆节，全国各地很多游人都会利用假期到北京来旅游。要是你能到天安门广场去看看，就会知道，这个古老的国家如今显得多么年轻，你就会感到，勤劳善良、热爱和平的中国人是多么热情。也许你会爱上这个美丽的城市，爱上这些热情友好的人们。",
        "py": "Guóqìng Jié fàngjià qījiān, zhèng shì Běijīng yì nián zhōng fēngjǐng zuì měi de shíhou. Měi dào Guóqìng Jié, quánguó gèdì hěn duō yóurén dōu huì lìyòng jiàqī dào Běijīng lái lǚyóu. Yàoshi nǐ néng dào Tiān'ānmén Guǎngchǎng qù kànkan, jiù huì zhīdào, zhè ge gǔlǎo de guójiā rújīn xiǎnde duōme niánqīng, nǐ jiù huì gǎndào, qínláo shànliáng, rè'ài hépíng de Zhōngguórén shì duōme rèqíng. Yěxǔ nǐ huì àishàng zhè ge měilì de chéngshì, àishàng zhèxiē rèqíng yǒuhǎo de rénmen.",
        "vi": "Kỳ nghỉ Quốc khánh đúng vào lúc Bắc Kinh có phong cảnh đẹp nhất năm. Mỗi dịp Quốc khánh, nhiều du khách từ khắp cả nước tận dụng kỳ nghỉ để tới Bắc Kinh. Nếu có dịp đến quảng trường Thiên An Môn, bạn sẽ thấy đất nước lâu đời này ngày nay trẻ trung biết bao, và cảm nhận được người Trung Quốc cần cù, lương thiện, yêu hòa bình nhiệt tình đến nhường nào. Có lẽ bạn sẽ yêu thành phố xinh đẹp này và những con người nhiệt tình, thân thiện ấy."
