    "workbook": {
      "exercisesNote": "Trang 30, câu hỏi đọc hiểu.\n1. 北京一年有几个季节？每个季节从几月到几月？你们国家呢？\n2. 北京的春天怎么样？\n3. 北京的夏天怎么样？\n4. 北京的冬天怎么样？\n5. 北京的秋天怎么样？\n6. 你们国家或家乡的四季怎么样？请写出来并说一说。\n\nLuyện ngữ âm và đọc cụm từ, mục 1–2 tr. 34–35. Hoàn thành câu và hội thoại, mục 4–5 tr. 36. Liên kết câu thành đoạn văn, mục 6 tr. 37. Nói theo tình huống, mục 8 tr. 38.\n\nMục 9, tr. 38. 一把雨伞\n去年秋天的一个星期天，我和爱人带①____孩子去爬山。刚刚两岁的儿子，玩得很高兴。这时，一阵风刮来，抬头一看，刚才还是蓝蓝的天上，不知什么时候起②____黑云。很快就开始掉雨点了，我和爱人一下子着急了，从这儿往前，离车站还远，往回走，也要将近一个小时，我们又没带雨伞。③____越下越大，我抱④____儿子，不知怎么办好。正在这时，一对年轻人打着一⑤____雨伞向我们这边走来，看到我们的样子，两人一笑，马上⑥____伞送给我们，说：“孩子小，淋了雨会感冒的。”然后，⑦____俩说着笑着淋着雨跑远了。\n雨中的经历使我常想起这两个不知姓名的年轻人，只知道他们在北京工作，但是因为当时没有留下姓名和地址，⑧____这把雨伞现在还放在我们家里。",
      "answerKeyNote": "Phụ lục tr. 174.\nMục 6. (1) B D C A, (2) D B A C.\nMục 7. (1) 我很喜欢北京，大街上有很多树，很绿。\n(2) 中国的大街上到处是自行车。\n(3) 我把房间打扫干净了。\n(4) 她生病了，可是她不想去医院打针。\n(5) 这个周末你想不想去旅行？ Câu gốc dùng 星期末, cách sửa của sách là 周末.\n(6) 我非常爱我的女朋友。\nMục 9. (1) 着, (2) 了, (3) 雨, (4) 起 / 着, (5) 把, (6) 把, (7) 他们, (8) 所以."
    },
