    "workbook": {
      "exercisesNote": "Trang 41, câu hỏi đọc hiểu.\n1. “我”为什么要学习中文？你呢？\n2. “我”第一次来中国是什么时候？来做什么？\n3. “我”在旅途中遇到了什么困难？是谁帮助了她？\n4. “我”为什么还要来中国？“我”的理想是什么？你呢？\n5. “我”学会了一支什么歌？你听过这支歌吗？\n6. “我”来中国多长时间了？我为什么常常一个人偷偷地哭？你哭过吗？为什么？\n7. “我”为什么要坚持下去？为什么觉得自己很可笑？\n\nLuyện ngữ âm và đọc cụm từ, mục 1–2 tr. 46–47. Hoàn thành câu và hội thoại, mục 4–5 tr. 48. Liên kết câu thành đoạn văn, mục 6 tr. 49. Nói theo tình huống, mục 8 tr. 50.\n\nMục 9, tr. 50–51. 钥匙链\n在国外的最后几天，因为口袋里还剩下一些钱，就想把它全花①____，给可爱的女儿买件礼物带②____去。正好那天我们去海洋世界游玩，我终于找到了想买的东西。\n那是一个小小的钥匙链儿，③____有一只胖胖的企鹅，样子十分可爱，看起来还带异国风情。既然到了异国他乡，当然要买带有异国色彩的礼物。我挑④____半天，一下子买了七八个。回到宾馆，朋友们见我买的钥匙链，⑤____说好，还问我在哪儿买的，他们也想去买一些回去送人。\n回到家，我急不可待地把礼物拿出来给女儿看，并告诉她这些都是澳洲的特产，我为了买这些礼物是多么辛苦，澳洲的艺术品又是多么的好，女儿高兴⑥____接过去，反复地看着，看样子也很喜欢。忽然她叫了一声：“妈，你快来看，这里写的是什么？”我过去仔细一看，上面一行小字清楚地写⑦____：“Made in China”。啊！⑧____是中国制造的。女儿哈哈笑了起来，指着我说：“我的老妈呀，你可真聪明啊！”",
      "answerKeyNote": "Phụ lục tr. 174–175.\nMục 6. (1) B A C D, (2) A D C B E.\nMục 7. (1) 听了她的话，我心里热乎乎的。\n(2) 这是很自然的事，哪国人都会这样。\n(3) 我昨天晚上做了一个梦，梦见了我的朋友。\n(4) 跟朋友分别的时候，心里很难过。\n(5) 我不愿意太麻烦你。\n(6) 他用照相机把我吃饭的样子拍／照了下来。\nMục 9. (1) 了, (2) 回, (3) 上面, (4) 了, (5) 都, (6) 地, (7) 着, (8) 原来."
    },
