        "py": "Nà tiān, wǒ zài Jiànguómén shàng le dìtiě. Zhè shì wǒ lái Zhōngguó hòu dì-yī cì zuò dìtiě, yǐqián cónglái méiyǒu zuòguo Zhōngguó de dìtiě. Chē shang rén hěn duō, xià le dìtiě, shàng dào dìmiàn shí, wǒ cái fāxiàn nà bú shì wǒ yào qù de dìfang, yīnwèi méiyǒu zhǎodào shúxī de sānbǎi qīshíwǔ lù qìchē zhàn.",
