        "py": "Tāmen shuō, sānbǎi qīshíwǔ lù chēzhàn zài Xīzhímén, ér zhèr shì Fùxīngmén, lí Xīzhímén hái yuǎn zhe ne. Dāng tāmen zhīdào wǒ yào huí xuéxiào shí, jiù shuō: “Shàng chē ba, wǒmen zhènghǎo yào qù Yíhéyuán fāngxiàng, kěyǐ dài nǐ yí duàn.”",
