        "zh": "我家院子里有一棵葡萄树，几年来一直半死不活的。不料，去年竟然长出了许多叶子，还结了许多葡萄。",
        "py": "Wǒ jiā yuànzi li yǒu yì kē pútaoshù, jǐ nián lái yìzhí bàn sǐ bù huó de. Búliào, qùnián jìngrán zhǎngchū le xǔduō yèzi, hái jiē le xǔduō pútao.",
        "vi": "Trong sân nhà tôi có một cây nho, mấy năm nay cứ sống dở chết dở. Nào ngờ năm ngoái cây lại mọc rất nhiều lá, còn sai quả nữa."
