        "zh": "我说不要钱，只是想请他尝尝。他不愿意，说不能白吃，坚持要付钱。没办法，我只好收下了他的钱。",
        "py": "Wǒ shuō bú yào qián, zhǐshì xiǎng qǐng tā chángchang. Tā bú yuànyì, shuō bù néng bái chī, jiānchí yào fù qián. Méi bànfǎ, wǒ zhǐhǎo shōuxià le tā de qián.",
        "vi": "Tôi nói không lấy tiền, chỉ muốn mời anh nếm thử. Anh không chịu, bảo không thể ăn không, cứ nhất quyết đòi trả tiền. Tôi chẳng còn cách nào đành nhận tiền của anh."
