        "py": "Wǒ bǎ pútao sòng gěi yí wèi lǐngdǎo. Tā jiēguo wǒ de pútao hòu yìzhí zhùshì zhe wǒ, ránhòu dīshēng wèn: “Nǐ yǒu shénme shì yào bàn ma?” Wǒ gàosu tā, wǒ méiyǒu shénme shì, zhǐshì xiǎng ràng tā chángchang zhè kē lǎoshù jiē de xīn pútao.",
