    "chars": [],
    "workbook": {
      "exercisesNote": "Trả lời theo bài đọc (tr. 67).\n1. 作者为什么要把葡萄送给别人吃？\n2. 作者送的第一个是什么人？他是什么态度？\n3. 作者送的第二个是什么人？他为什么问“你有什么事要办吗？”\n4. 作者送的第三个是什么人？他们为什么吵架？\n5. 作者送的第四个是什么人？他是什么态度？\n\nLuyện tập tr. 72–77.\nMục 1–2: Phân biệt âm, thanh điệu, đọc cụm từ (tr. 72–73).\nMục 3: Chọn từ điền trống (tr. 73–74).\nMục 4: Hoàn thành câu bằng 不料、竟然、也许、只好、只是、意外 (tr. 74).\nMục 5: Hoàn thành hội thoại bằng 半死不活、不料、意外、看得出、并不 (tr. 74–75).\nMục 6: Liên kết câu thành đoạn (tr. 75).\n(1) A. 因此，来中国留学后，我就在音乐学院找了一位老师教我弹琵琶\nB. 他留给我最初的印象是太严厉，脸上没有一点儿笑容\nC. 来中国以前，我就觉得中国的琵琶非常神奇，也非常有意思\nD. 和老师第一次见面时我有点儿不好意思\n(2) A. 保持着读书人那种“心底无私天地宽”的品格\nB. 我的老师都是很好的人，他们的待遇虽然远没有国外的高\nC. 对外面花花绿绿的世界，他们的心里很平静\nD. 可他们似乎不太在乎这些\nE. 因此，我感到很幸运，遇到了这么好的老师，他们的优秀品格将影响我的一生\nMục 7: Sửa câu sai (tr. 75–76).\nMục 8: Biểu đạt theo tình huống (tr. 76).\nMục 9: Điền từ vào bài 换换搭档 và đọc nhóm từ bổ sung (tr. 77).",
      "answerKeyNote": "Đáp án tham khảo tr. 176.\nMục 6: (1) C A D B; (2) B D C A E.\nMục 7:\n1. 虽然我们两个认识的时间不长，但很快成了好朋友。\n2. 今天该上口语课，不料老师没来。\n3. 每次舞会她都不参加，没想到今天她竟然来了。\n4. 她是我的老师，也是我的朋友。\n5. 星期六晚上我都睡得特别晚。\n6. 校园里的花开得非常好看。\nMục 9: 1. 在 · 2. 个 · 3. 的 · 4. 得 · 5. 得 · 6. 去 · 7. 要／让 · 8. 上."
    },
