    "workbook": {
      "answerKeyNote": "Sửa câu sai\n1. 她已经病了好几天了，我们都不知道。\n2. 既然病了，就不要去上课了。\n3. 这些都是我学过的生词，所以我记住了。\n4. 不管天气好不好，我们都得去上课。\n5. 不管这个问题多么难，我们都得把它解决。\n6. 不管下多大雨，我们也不怕。\n7. 不但他没上课，而且我也没去。\n8. 老师的问题，不但我不会回答，她也不会回答。\n\nĐiền tổng hợp\n1. 河\n2. 把\n3. 去\n4. 从\n5. 去\n6. 找",
      "exercisesNote": "Trả lời theo bài đọc, tr. 80: 南郭先生为什么能混进乐队里去？ 后来南郭先生为什么溜走了？ 那个卖矛又卖盾的人是怎么叫卖的？ 别人问了他一个什么问题？\nLuyện tập tr. 86–91. Mục 6 nối đoạn tr. 89, đáp án 1. CBDA, 2. CADB (tr. 176). Mục 7 sửa câu tr. 89–90, đáp án tr. 176–177. Mục 9 điền “刻舟求剑” tr. 91, đáp án tr. 177.\n刻舟求剑\n从前，有一个人坐船过①____，船走到河中间的时候，不小心②____身上带的剑掉到河里③____了。他马上在船上刻了一个记号，还自言自语地说：“我的剑就是④____这儿掉到河里去的。”\n船在河里走了好久，终于到了岸边。这个人急忙从船上刻着记号的地方跳下水⑤____，找他的剑。你想，他怎么能⑥____到他的剑呢？\n这也是中国一个很有名的成语故事，名字叫“刻舟求剑”。"
    },
