    "workbook": {
      "answerKeyNote": "Sửa câu sai\n1. 她是一个又漂亮又聪明的姑娘，我很喜欢她。\n2. 我很爱她，但是她并不知道。\n3. 他失恋了，很痛苦。\n4. 最近我的心里很矛盾，不知道出国留学好呢，还是在国内上大学好。\n5. 他一连三天没上课了。\n6. 请大家尽情地唱吧。\n\nĐiền tổng hợp\n1. 了\n2. 很 / 非常／特别\n3. 同 / 一样\n4. 我们\n5. 可\n6. 我\n7. 了\n8. 谁",
      "exercisesNote": "Đọc hiểu tr. 93: 赵霞是一个什么样的女孩儿？你遇到过这样的女孩儿吗？ 为什么“我”看到余辉和赵霞在一起，心里就有一种说不出的滋味？你尝过这样的滋味吗？ “我”为什么尽量不跟他们在一起？ “我”病了，为什么还觉得很开心？ 赵霞到底喜欢谁？ 当知道赵霞喜欢自己的时候，“我”是什么感觉？ “我”的心里为什么很矛盾？如果是你，你会怎么办？ 赵霞跟“我”好的消息是什么时候公开的？ “我”处理问题的方法你赞成吗？为什么？\nLuyện tập tr. 98–103. Mục 6 nối đoạn tr. 101, đáp án 1. DCBA, 2. DACB (tr. 177). Mục 7 sửa câu tr. 101–102 và mục 9 điền “等待” tr. 103, đáp án tr. 177.\n等待\n半个月前，我和男朋友吵①____一架，到现在我们都不说话，我心里②____难过。原因是我们对一件事的看法不③____。他觉得这件事他做得对，可我觉得自己也没有错。④____各自坚持自己的看法，互不相让。我这个人平时很随和，⑤____这件事我觉得不能让步。半个月了，⑥____很想跟他和好，可又迈不出第一步。我还在等待，等着他主动跟我和好，如果他还不主动，只好我主动⑦____，没办法，⑧____让我爱他呢？"
    },
