    "workbook": {
      "exercisesNote": "Trả lời câu hỏi đọc hiểu (tr. 118).\n1. 这个人为什么想辞职？\n2. 他的朋友向他提出了什么建议？\n3. 他听从朋友的建议了没有？\n4. 一年以后这个人为什么又不想辞职了？\n5. 领导为什么会对他刮目相看？\nMục 1–2 luyện ngữ âm và cụm từ tr. 124–125. Mục 3 chọn từ tr. 125–126. Mục 4–5 hoàn thành câu và hội thoại tr. 126–127. Mục 6 sắp xếp câu tr. 127. Mục 7 sửa câu tr. 127–128. Mục 8 biểu đạt theo tình huống tr. 128. Mục 9 điền tổng hợp 《从头再来》 và từ bổ sung tr. 128–129.",
      "answerKeyNote": "Phụ lục tr. 178.\nMục 6: (1) D B C A; (2) C D B A E.\nMục 7:\n1. 他已经辞职了，接着就要去中国留学。\n2. 他想让老师对他刮目相看。\n3. 一般的中国电影他不太喜欢，但这个电影她却很喜欢。\n4. 我虽然很爱她，但她不喜欢我，没办法。\n5. 我没有给妈妈打电话，妈妈埋怨我了。／我没有给妈妈打电话，妈妈说我了。\n6. 在北京骑自行车比在香港容易。\nMục 9: (1) 进; (2) 了; (3) 要; (4) 下去; (5) 着; (6) 的; (7) 起来; (8) 更."
    },
