        "py": "Dà Liú liánmáng pǎo chūqu le. Wǒ bù zhī fāshēng le shénme shì, réngrán dīzhe tóu zài fā shǒujī duǎnxìn. Zhè shí, Dà Liú yòu mǎshàng huílai, yòng lì qiāozhe wǒ de mén dà jiào: ‘Kuài, kuài chūlai!’ Wǒ mǎshàng yìshí dào fāshēng le bù xúncháng de shìqing. Yúshì, wǒ hé fángjiān li de rén lìjí pǎo le chūqu.",
        "vi": "Đại Lưu vội chạy ra ngoài. Tôi chẳng biết có chuyện gì, vẫn cúi đầu nhắn tin. Lúc ấy anh quay lại ngay, đập mạnh vào cửa phòng tôi và hét lớn “Mau, mau ra đây!” Tôi lập tức nhận ra có chuyện khác thường, liền cùng những người trong phòng chạy ra."
