        "zh": "突然，飞碟朝我们这边儿直冲下来。我以为它要降落了，可飞碟却停住了，又向高空慢慢飞去。然后一闪，变成了一个星星一样的亮点儿。接着又一闪，不见了。从一个唱片大小的碟子只是一闪就变成了一个小亮点儿，这是多么快的速度啊！只是它留下的光束在空中亮了半天才一点点地暗下去。差不多一个小时以后，天空才渐渐恢复到原来的一片蓝色。",
        "py": "Tūrán, fēidié cháo wǒmen zhèbiānr zhí chōng xiàlai. Wǒ yǐwéi tā yào jiàngluò le, kě fēidié què tíngzhù le, yòu xiàng gāokōng mànmàn fēi qù. Ránhòu yì shǎn, biànchéng le yí ge xīngxing yíyàng de liàngdiǎnr. Jiēzhe yòu yì shǎn, bú jiàn le. Cóng yí ge chàngpiàn dàxiǎo de diézi zhǐ shì yì shǎn jiù biànchéng le yí ge xiǎo liàngdiǎnr, zhè shì duōme kuài de sùdù a! Zhǐshì tā liúxià de guāngshù zài kōngzhōng liàng le bàntiān cái yì diǎndiǎn de àn xiàqu. Chàbuduō yí ge xiǎoshí yǐhòu, tiānkōng cái jiànjiàn huīfù dào yuánlái de yí piàn lánsè.",
        "vi": "Đột nhiên đĩa bay lao thẳng về phía chúng tôi. Tôi tưởng nó sắp đáp xuống, nhưng nó dừng lại rồi từ từ bay lên cao. Sau đó nó lóe lên, biến thành một đốm sáng như ngôi sao. Lóe thêm một lần nữa rồi mất hút. Chỉ trong chớp mắt, chiếc đĩa cỡ đĩa hát đã biến thành một chấm sáng nhỏ, tốc độ nhanh biết bao! Chỉ có chùm sáng nó để lại còn rực rất lâu rồi tối dần. Gần một giờ sau, bầu trời mới dần trở lại màu xanh ban đầu."
