    "workbook": {
      "exercisesNote": "Câu hỏi đọc hiểu, tr. 132.\n1. 故事发生在什么时间？什么地方？\n2. 那儿的风景怎么样？\n3. 大刘叫“我”的时候“我”正在做什么？\n4. 大刘为什么叫“我”？\n5. 他们看见了什么东西？\n6. 课文是怎么描述飞碟的？\n\nNgữ âm, thơ và cụm từ tr. 138–139. Hoàn thành câu và hội thoại tr. 140–141. Nối đoạn tr. 141–142. Luyện nói theo tình huống tr. 142–143.\n\nMục 9 tr. 143, 我真傻\n我们已进入期末考试的紧张时刻，每天都忙①____团团转。一天，我们班在电脑教室上课。下课②____，我在课桌上发现一本电脑书，以为是同桌韩玲③____，可她手里正拿着自己的书。我想，肯定是我们班同学的，干脆先拿回班里去再④____。在班里我问了个遍，没想到同学们都说没丢电脑书。我就顺手把课本放在了讲台上。\n放学了，我背着书包经过讲台旁，又看了一眼那本电脑书，心想看看书中的字迹，也许能认⑤____它的主人，⑥____我就翻了一下。翻来翻去，忽然觉得不对劲儿，这笔迹怎么这么熟悉？这不是我的字迹吗？噢！我想起来了：上电脑课时，我看自己的电脑书的书皮破了，就顺手把书皮去掉放在了课桌里，下了课，合⑦____书就不认识它了，⑧____大声叫着替它找主人呢。你说我傻不傻？",
      "answerKeyNote": "Phụ lục tr. 179.\nMục 6. (1) D A C B, (2) B A D C.\nMục 7. (1) 因为是个新电影，大家都争着买票看。\n(2) 秋天一到，商店里有各种各样的水果。／秋天一到，有各种各样的水果。\n(3) 我走路上街的时候，被一辆自行车撞伤了。\n(4) 抬头一看，只见天空有很多星星。\n(5) 太阳已经落了，我们快下山去吧。\nMục 9. (1) 得, (2) 后／以后, (3) 的, (4) 说, (5) 出, (6) 于是, (7) 上, (8) 还."
    },
