    "workbook": {
      "exercisesNote": "Câu hỏi đọc hiểu, tr. 147.\n1. 那个孩子的妈妈为什么对他吼？\n2. 朋友们为什么说他是个“马大哈”？\n3. 在公园里他为什么被误解？\n4. 他是怎么把姑娘的自行车胎打爆的？\n\nNgữ âm, tục ngữ và cụm từ tr. 152–153. Hoàn thành câu và hội thoại tr. 153–154. Nối đoạn tr. 154–155. Nói theo tình huống tr. 155–156.\n\nMục 9 tr. 156–157, 春天的故事\n听到门响，知道是丈夫回来①____。\n“晚上车顺利吧？”\n没有回答，想是有话要说，我便抬起头来。\n“挺顺利的。”丈夫说。目光却望②____窗外。\n“车上有一个女孩儿，好像没来过这边儿，问方村还有几站，我告诉了她，一起下车后，见她犹犹豫豫地四处张望，我很想问她去哪儿，为她指路或送她一段。可是还是走开了。怕她把我③____坏人，搞得不愉快。”\n说完了，丈夫那表情好像做错了什么事似的，没再说话。\n窗外，雨还在轻轻地下着，风吹了进来。今年的春天有些特别，代替往年那漫天黄风的是几场不大不小的春雨。虽然人们有点儿抱怨，但那树枝却诚心诚意地绿了起来。不知不觉中，我的心里突然有一股不是痛苦，不是甜蜜，不是感伤，不是欣喜的滋味。\n几天前，也是这样一个下雨的晚上，从朋友家出④____，到车站坐车回家。在风雨中我拉紧了衣领，来回走着，着急地等着车，心想，车来之前一定会被淋成个落汤鸡。忽听身边一个很低却很清晰的男声说：“站到这伞下来吧。”我忽然收住了脚，“哦，不！”我本能地回答那黑暗中的声音，却没再动。陌生男人转过脸对着马路，过了几秒钟又说：“站过来吧！雨下⑤____这么大！”不知是这声音里的命令意味，还是那高大的个子在沉默中显示的魅力，⑥____我产生了想冒险的冲动，于是迈了一步站到了他的伞下。听得到自己心里咚咚直跳，装作很镇静地抬头看看那伞。那伞已经破了，雨水滴到陌生男人的肩上，那张脸仍镇静地面对马路。车很快就来了，我这才松了一口气，轻声地道了谢，⑦____头也不回地跳上车，感受到的仍是背后的目光。\n窗外仍然是细细的雨声。\n这时我也开始胡思乱想⑧____来，那小女孩儿是否被淋湿了？她是否顺利地找到了要去的地方？不知那低声男子是否还记得，那天在车站他的好意换来的是我的一脸警惕？不知他后来是否还肯在黑夜中与淋湿的路人共享一些温暖？真愿大家都能多一些爱心，少一些戒心，多一些信任，少一些怀疑。\n有了这场春雨，今年的春天会更美，我想。",
      "answerKeyNote": "Phụ lục tr. 179–180.\nMục 6. (1) C D E A B, (2) C A E D B.\nMục 7. (1) 他的汉语说得很好，他很得意。／他感到得意的是自己的汉语说得不错。\n(2) 我要赶快交作业，免得老师批评。／我要按时交作业，免得老师批评。\n(3) 纪念碑前的鲜花表示人们对烈士们的悼念。\n(4) 尽管我很努力，但是考试的成绩不太好。\n(5) 你再提醒他一声，免得他忘了。\n(6) 我碰了他一下，连忙说了声：“对不起。”\nMục 9. (1) 了, (2) 着, (3) 当／当成, (4) 来, (5) 得, (6) 使, (7) 就, (8) 起."
    },
