    "notes": [
      "老大 (tr. 162) là con cả. 老二 và 老三 lần lượt chỉ người con thứ hai và thứ ba.",
      "以……为主 (tr. 162) nghĩa là lấy điều gì làm chính. 以种地为主 là lấy nghề làm ruộng làm chính.",
      "在家千日好，出门一时难 (tr. 162) là tục ngữ nói cuộc sống xa nhà khó khăn hơn ở nhà.",
      "Trong 我自己的事三年内不考虑 (tr. 162), 自己的事 chỉ chuyện tái hôn.",
      "Mục lục có 家教 trong nhóm chú thích. Ở trang in 162, mục (四) là 我自己的事三年内不考虑; 家教 xuất hiện trong danh sách từ mới tr. 161."
    ],
    "chars": [],
    "workbook": {
      "exercisesNote": "Trả lời theo bài đọc (tr. 159).\n1. 打工青年高明为什么觉得自己“挺难的”？\n2. 电视台编辑李文的日子过得怎么样？他现在为什么不想解决自己的个人问题？\n3. 歌手克风为什么不把母亲接到自己身边？他是不孝吗？\n\nLuyện tập tr. 167–172.\nMục 1–2: Luyện âm, đọc tục ngữ và cụm từ (tr. 167).\nMục 3: Chọn từ điền trống (tr. 168). Mục 4–5: Hoàn thành câu và hội thoại (tr. 169–170).\nMục 6: Liên kết câu thành đoạn (tr. 170).\n(1) A. 还说动物中鸟类的语言和人类的语言几乎一样多，虽然它们发出的只是不同的声音，还不能算作语言\nB. 报上说，世界上人类的语言有两千七百多种\nC. 报告中说，像人类那样，一种鸟类也爱学习别的鸟类的语言\nD. 动物学家通过考察，写出了一份有趣的鸟类语言的报告\n(2) A. 因此，维护大气圈的良好状态已成为各国人民的共同要求\nB. 大气中的二氧化碳逐渐增加，地球表面散热作用越来越弱\nC. 科学家指出，目前，由于人类大量燃烧煤、石油、天然气\nD. 如果这样下去，地球上的气温可能会越来越高，严重影响人类的生存\nMục 7: Sửa câu sai (tr. 170–171). Mục 8: Biểu đạt theo tình huống (tr. 171).\nMục 9: Điền từ vào bài 徐霞客 và đọc từ bổ sung (tr. 172).",
      "answerKeyNote": "Đáp án tham khảo tr. 180.\nMục 6: (1) B D C A; (2) C B D A.\nMục 7:\n1. 哪怕今天再忙，我都要把这本书看完。\n2. 我们都喜欢看这个电影，他却不喜欢。\n3. 日本同学说，日语很容易学，但是我觉得很难学。\n4. 现在春天了，天气不但不暖和，反而很冷。\n5. 她没来过中国，很想来中国。\n6. 她考试不太好，觉得很没脸／很丢人。\nMục 9: (1) 的; (2) 他; (3) 来; (4) 感到; (5) 对; (6) 座; (7) 出／成; (8) 又."
    },
